// Simple global store for options (single-threaded / best-effort).
static mut PRINT_OPTIONS: Option<PrintOptions> = None;

fn with_options_mut<R>(f: impl FnOnce(&mut PrintOptions) -> R) -> R {
    unsafe {
        if PRINT_OPTIONS.is_none() {
            PRINT_OPTIONS = Some(PrintOptions::default());
        }
        f(PRINT_OPTIONS.as_mut().unwrap())
    }
}

fn set_printoptions(
    precision: Option<u8>,
    threshold: Option<u8>,
    edgeitems: Option<u8>,
    linewidth: Option<u8>,
    suppress: Option<bool>,
    nanstr: Option<String>,
    infstr: Option<String>,
    sign: Option<String>,
    floatmode: Option<String>,
    legacy: Option<String>,
) -> () {
    with_options_mut(|opt| {
        if let Some(p) = precision {
            assert!(p > 0);
            opt.precision = p;
        }
        if let Some(t) = threshold {
            assert!(t > 0);
            opt.threshold = t;
        }
        if let Some(e) = edgeitems {
            assert!(e > 0);
            opt.edgeitems = e;
        }
        if let Some(w) = linewidth {
            assert!(w > 0);
            opt.linewidth = w;
        }
        if let Some(s) = suppress {
            opt.suppress = s;
        }
        if let Some(ns) = nanstr {
            assert!(!ns.is_empty());
            opt.nanstr = ns;
        }
        if let Some(is_) = infstr {
            assert!(!is_.is_empty());
            opt.infstr = is_;
        }
        if let Some(sg) = sign {
            let mut it = sg.chars();
            let c = it.next().expect("sign must be non-empty");
            assert!(it.next().is_none(), "sign must be a single character");
            assert!(c == '-' || c == '+' || c == ' ');
            opt.sign = c;
        }
        if let Some(fm) = floatmode {
            assert!(
                fm == "fixed" || fm == "unique" || fm == "maxprec" || fm == "maxprec_equal"
            );
            opt.floatmode = fm;
        }
        if let Some(lg) = legacy {
            assert!(lg == "1.13" || lg == "1.21" || lg == "1.25" || lg == "2.1" || lg == "2.2");
            opt.legacy = lg;
        }
    });
}